arguments.new_str:
    // .NET 9 breaking change: on Linux, empty env vars now return ""
    // instead of null. Use a direct null check against the environment
    // to distinguish "not set" from "explicitly empty".
    var val = Environment.GetEnvironmentVariable("MY_FLAG");
    if (val is null && !IsEnvironmentVariableSet("MY_FLAG"))
    {
        Console.WriteLine("MY_FLAG not set, using default");
    }
}

static bool IsEnvironmentVariableSet(string variable)
{
    // IDictionary.Contains checks the process environment block directly;
    // an empty-string entry means "set but empty".
    return Environment.GetEnvironmentVariables().Contains(variable);
}

